// Owned byte-stream fixture: imports state machine only; cannot spawn processes.
mod eclair_backtrace;use eclair_backtrace::*;
fn feed(s:&mut Session,text:&str)->Vec<String>{s.feed(text.as_bytes()).unwrap()}
#[test]fn complete_threads_and_unknown(){let mut s=Session::default();assert_eq!(feed(&mut s,"(eclair) "),["info threads\r"]);assert_eq!(feed(&mut s,"threads listing\r\n(eclair) "),["thread 1\r"]);assert_eq!(feed(&mut s,"worker 1\r\n(eclair) "),["bt\r"]);assert_eq!(feed(&mut s,"#0 app\r\n(eclair) "),["thread 2\r"]);assert_eq!(feed(&mut s,"Unknown thread 2.\r\n"),["quit\r"]);assert_eq!(feed(&mut s,"Quit anyway? (y or n) "),["y\r"]);assert_eq!(s.state,State::Finished);}
#[test]fn skip_unknown_frames(){let mut s=Session::default();feed(&mut s,"(eclair) ");feed(&mut s,"(eclair) ");assert!(feed(&mut s,"0x123 in ?? ()\r\n").is_empty());assert_eq!(s.state,State::ThreadSkip);assert_eq!(feed(&mut s,"(eclair) "),["thread 2\r"]);}
#[test]fn pagination(){let mut s=Session::default();feed(&mut s,"(eclair) ");assert_eq!(feed(&mut s,"Type <RET> for more, q to quit, c to continue without paging--"),["\r"]);assert_eq!(feed(&mut s,"Type <return> to continue, or q <return> to quit"),["\r"]);feed(&mut s,"(eclair) (eclair) ");assert_eq!(s.state,State::ThreadBt);assert_eq!(feed(&mut s,"Type <RET> for more, q to quit, c to continue without paging--"),["q\r"]);assert_eq!(feed(&mut s,"Type <return> to continue, or q <return> to quit"),["\r"]);feed(&mut s,"in ?? ()");assert_eq!(feed(&mut s,"Type <return> to continue, or q <return> to quit"),["q\r"]);}
#[test]fn every_byte_chunk_boundary(){let transcript="(eclair) thread listing\r\n(eclair) frame\r\n(eclair) backtrace\r\n(eclair) Unknown thread 2\r\nQuit anyway? (y or n) ";let mut s=Session::default();let mut sent=Vec::new();for b in transcript.as_bytes(){sent.extend(s.feed(&[*b]).unwrap());}assert_eq!(sent,["info threads\r","thread 1\r","bt\r","thread 2\r","quit\r","y\r"]);}
#[test]fn not_known_nested_dialogue(){let mut s=Session::default();assert!(feed(&mut s,"thread not known.").is_empty());assert_eq!(s.state,State::UnknownPrompt);assert!(feed(&mut s,"Unknown thread ignored").is_empty());assert_eq!(feed(&mut s,"(eclair) "),["quit\r"]);assert_eq!(feed(&mut s,"Quit anyway? (y or n) "),["y\r"]);assert_eq!(s.state,State::Finished);}
#[test]fn bounded_unmatched_output(){let mut s=Session::default();assert!(s.feed(&vec![b'x';1_000_000]).unwrap().is_empty());assert_eq!(feed(&mut s,"(eclair) "),["info threads\r"]);}
